import { Howl } from 'howler'
import { SoundEffects } from './types'

let soundsInstance: SoundEffects | null = null

export const getSounds = (): SoundEffects => {
    if (typeof window === 'undefined') {
        return {}
    }

    if (!soundsInstance) {
        soundsInstance = {
            siren: new Howl({
                src: ['/sounds/siren_loop.mp3'],
                loop: true,
                volume: 0.45,
                preload: true,
            }),
            starPing: new Howl({
                src: ['/sounds/star_ping.mp3', '/sounds/star_ping.wav'],
                volume: 1.0,
                preload: true,
            }),
            starFinal: new Howl({
                src: ['/sounds/star_final_hit.mp3', '/sounds/star_final_hit.wav'],
                volume: 1.0,
                preload: true,
            }),
            ambience: new Howl({
                src: ['/sounds/loading_ambience.mp3'],
                loop: true,
                volume: 0.45,
                preload: true,
            }),
            passed: new Howl({
                src: ['/sounds/mission_passed.mp3'],
                volume: 1.0,
                preload: true,
            }),
            failed: new Howl({
                src: ['/sounds/mission_failed.mp3'],
                volume: 1.0,
                preload: true,
            }),
            warningAccept: new Howl({
                src: ['/sounds/warning_accept.mp3', '/sounds/warning_accept.wav'],
                volume: 0.85,
                preload: true,
            }),
        }
    }

    return soundsInstance
}
